insert into public.idol_personas (slug, path_name, tagline, category, inspired_by, source_note, dossier, tags, is_active)
values ('greenlights-yolu','Greenlights Yolu','engeli fırsata çevirmek','sanat','Matthew McConaughey','Bu yol Matthew McConaughey''nin ''Greenlights'' (2020) kitabında anlattığı kamuya açık yaklaşımdan ilham alır; kendisiyle bağlantılı değildir.','{"why_important": "Hayat kırmızı ve sarı ışıklarla doludur; çoğu insan onları felaket sayıp durur. Bu yol engeli yön bilgisi olarak okur: bugün seni durduran şey, geriye dönünce rotanı düzelten şey olabilir. Zincir kırıldığında kendini suçlamak yerine ''bu kırmızı ışık bana ne öğretti?'' sorusunu sorar ve devam eder.", "core_beliefs": ["Her kırmızı ışık zamanla yeşile döner; mesele o dönüşe hazır konumlanmaktır.", "Zorluk ceza değil, yön bilgisidir.", "Kendine dürüst olmak, kendini affetmenin ön koşuludur.", "Az ama sürekli yapılan şey, çok ama düzensiz yapılandan güçlüdür."], "mindset": "Kabul ve eylem birlikte yürür: olanı olduğu gibi görmek pasiflik değil, doğru hamlenin ön koşuludur. Şikâyet yerine kayıt tutmak; duyguyu bastırmak yerine yazıya dökmek; başarısızlığı kimlik değil veri saymak.", "habits": ["Günlük tutmak: yaşananları ve çıkarılan dersi kısa notlarla kaydetmek.", "Zor günü sonradan yeniden okumak için işaretlemek.", "Doğada uzun yürüyüş sırasında sesli düşünmek.", "Hayır demeyi öğrenmek: enerji tüketen bir işi bilinçli bırakmak.", "Küçük riskleri bilerek almak (reddedilmeye alışma)."], "daily_routine": "Sabah kısa yazma ile niyet, gün içinde hareket, akşam tek paragraflık değerlendirme. Amaç katı program değil, güne başta ve sonda dönme alışkanlığıdır.", "sports_or_physical_practice": "Açık hava yürüyüşü/koşu; performans için değil zihinsel berraklık için.", "reading_profile": "Hayat hikâyeleri, felsefe ve otobiyografi; okurken not alma.", "books_read_or_recommended": ["Greenlights — Matthew McConaughey"], "decision_style": "Uzun vadeli değerlere göre eleme; kısa vadede cazip ama kimliğine uymayan seçenekleri reddetme.", "failure_and_recovery": "Başarısızlığı kırmızı ışık diye yazmak; tek dersi sonraki hamleye taşımak. Toparlanma kısa tutulur.", "public_quotes": ["Yeşil ışıklar, kırmızı ve sarı ışıkları nasıl okuduğuna bağlıdır. (Greenlights, 2020 — mealen)"], "lessons_for_users": ["Bugünün engelini tek cümleyle yaz; altına ''bu bana ne öğretti?'' ekle (5 dk).", "Bu hafta seni tüketen bir işe hayır de; yerine 10 dakikalık bir şey koy.", "Küçük bir risk al: reddedilme ihtimali olan tek bir mesaj gönder.", "Ay sonunda döndürdüğün üç engeli listele — yeşil ışık arşivi.", "Zincir kırıldıysa o günü işaretle; ertesi gün en küçük halkayı yap."], "sources": ["https://greenlights.com/", "https://www.penguinrandomhouse.com/books/575467/greenlights-by-matthew-mcconaughey/"]}'::jsonb,'{"direnç","engel","günlük","kabul"}'::text[],true)
